/**
 * R5. Aplica un color de fondo a la celda actualmente activa.
 */
function handleColorChange() {
    const activeCell = document.querySelector('#spreadsheet td[data-cell]:focus');
    const colorPicker = document.getElementById('background-color-picker');
    const selectedColor = colorPicker ? colorPicker.value : null;

    if (activeCell && selectedColor) {
        // Aplicar el estilo de fondo directamente al elemento DOM
        activeCell.style.backgroundColor = selectedColor;
    } else {
        console.warn("No hay una celda activa o no se pudo obtener el color.");
    }
}
