### FUNCION: deleteSelectedColumn
```javascript
function deleteSelectedColumn() {
    const selectedHeader = document.querySelector('.column-header.selected');
    if (!selectedHeader) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }
    const colLetter = selectedHeader.dataset.colLetter;

    if (!confirm(`¡ADVERTENCIA! ¿Estás seguro de que quieres ELIMINAR permanentemente la columna ${colLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 1. Eliminar los elementos DOM de las celdas y encabezados
    const cellsToRemove = document.querySelectorAll(`[data-cell^="${colLetter}"]`);
    cellsToRemove.forEach(cell => cell.remove());

    // 2. Eliminar el encabezado de la columna
    selectedHeader.remove();

    // 3. Reindexar y reajustar las columnas restantes (esto es complejo en JS puro, pero simularemos el efecto)
    const spreadsheetBody = document.querySelector('#spreadsheet tbody');
    let columnIndex = 0;
    const rows = spreadsheetBody.querySelectorAll('tr');

    rows.forEach(row => {
        // Recorrer las celdas de la fila y eliminar las que pertenecen a la columna borrada
        Array.from(row.cells).filter((cell, index) => cell.dataset.colLetter === colLetter).forEach(cell => {
            cell.remove();
        });
    });

    // 4. Reajustar los índices de las columnas restantes (esto es crucial para que data-cell siga siendo correcto)
    const remainingHeaders = document.querySelectorAll('.column-header');
    remainingHeaders.forEach((header, index) => {
        header.dataset.colLetter = String.fromCharCode(65 + index); // Reestablecer la letra A, B, C...
        header.textContent = header.dataset.colLetter;
    });

    // 5. Limpiar selección y notificar
    document.querySelectorAll('.column-header').forEach(h => h.classList.remove('selected'));
    alert(`Columna ${colLetter} eliminada exitosamente.`);
    console.log(`Columna ${colLetter} eliminada.`);
}
