    if (!selectedHeader) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }
    const colLetter = selectedHeader.dataset.colLetter;

    if (!confirm(`¡ADVERTENCIA! ¿Estás seguro de que quieres ELIMINAR permanentemente la columna ${colLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 1. Eliminar los elementos DOM de las celdas y encabezados
    const cellsToRemove = document.querySelectorAll(`[data-cell^="${colLetter}"]`);
    cellsToRemove.forEach(cell => cell.remove());

    // 2. Eliminar el encabezado de la columna
    selectedHeader.remove();

    // 3. Reajustar los índices y letras de las columnas restantes (A, B, C...)
    const remainingHeaders = document.querySelectorAll('.column-header');
    remainingHeaders.forEach((header, index) => {
        // Reestablecer la letra A, B, C...
        header.dataset.colLetter = String.fromCharCode(65 + index); 
        header.textContent = header.dataset.colLetter;
    });

    // 4. Limpiar selección y notificar
    document.querySelectorAll('.column-header').forEach(h => h.classList.remove('selected'));
    alert(`Columna ${colLetter} eliminada exitosamente.`);
    console.log(`Columna ${colLetter} eliminada.`);
}

