function selectRow(event) {
    const target = event.target;
    if (!target || !target.classList.contains('row-header')) return;

    // Deseleccionar cualquier fila previamente seleccionada
    document.querySelectorAll('.row-header').forEach(th => {
        th.style.backgroundColor = ''; // Reset color
        th.style.cursor = 'pointer';
    });

    // Seleccionar la nueva fila y guardar su referencia
    const rowElement = target.closest('tr');
    if (rowElement) {
        selectedRowElement = rowElement;
        target.style.backgroundColor = '#e0e0ff'; // Indicador visual de selección
        console.log(`Fila ${target.innerText} seleccionada.`);
    } else {
        selectedRowElement = null;
    }
}
